def parse_amount(text):
    """Turn text like '250' or '₹1,200' into a positive float, or raise ValueError."""
    cleaned = text.strip().replace("₹", "").replace(",", "")
    try:
        amount = float(cleaned)
    except ValueError:
        raise ValueError(f"'{text}' is not an amount")
    if amount <= 0:
        raise ValueError("amount must be more than zero")
    return round(amount, 2)

def add_expense(expenses, amount, category, note):
    """Append one expense dict to the list and return it."""
    expense = {"amount": amount, "category": category, "note": note}
    expenses.append(expense)
    return expense


def list_expenses(expenses):
    """Print every expense numbered from 1, or No expenses yet."""
    if not expenses:
        print("No expenses yet")
    for number, e in enumerate(expenses, start=1):
        print(f"{number}. ₹{e['amount']:.2f}  {e['category']}  {e['note']}")


def totals_by_category(expenses):
    """Return a dict mapping each category to its total amount."""
    totals = {}
    for e in expenses:
        totals[e["category"]] = totals.get(e["category"], 0) + e["amount"]
    return totals


def delete_expense(expenses, number):
    """Remove and return expense `number` (counting from 1), or raise ValueError."""
    if number < 1 or number > len(expenses):
        raise ValueError(f"no expense number {number}")
    return expenses.pop(number - 1)


expenses = []
print("Expense tracker. Commands: add, list, total, delete, quit")
while True:
    parts = input("> ").split()
    if not parts:
        continue
    command, *args = parts
    if command == "quit":
        print("Bye!")
        break
    elif command == "add":
        if len(args) < 2:
            print("Error: use add <amount> <category> <note>")
            continue
        try:
            amount = parse_amount(args[0])
        except ValueError as err:
            print("Error:", err)
            continue
        expense = add_expense(expenses, amount, args[1].lower(), " ".join(args[2:]))
        print(f"Added ₹{expense['amount']:.2f} to {expense['category']}")
    elif command == "list":
        list_expenses(expenses)
    elif command == "total":
        totals = totals_by_category(expenses)
        for category in sorted(totals, key=totals.get, reverse=True):
            print(f"{category}: ₹{totals[category]:.2f}")
        print(f"Total: ₹{sum(totals.values()):.2f}")
    elif command == "delete":
        if len(args) != 1:
            print("Error: use delete <number>, like delete 2")
            continue
        try:
            number = int(args[0])
        except ValueError:
            print(f"Error: '{args[0]}' is not an expense number")
            continue
        try:
            delete_expense(expenses, number)
        except ValueError as err:
            print("Error:", err)
            continue
        print("Deleted expense", number)
    else:
        print("Unknown command:", command)

