def over_budget(totals, budgets):
    """Return a sorted list of categories that spent more than their budget."""
    return sorted([c for c, spent in totals.items() if c in budgets and spent > budgets[c]])


totals = {"food": 3400, "travel": 900, "fun": 1500}
budgets = {"food": 3000, "travel": 2000}
print(over_budget(totals, budgets))

